// CHECK-NEXT:    [[ASMRESULT1:%.*]] = extractvalue { i64, i32 } [[TMP1]], 1
// CHECK-NEXT:    store i64 [[ASMRESULT]], ptr [[TMP0]], align 4
// CHECK-NEXT:    store i32 [[ASMRESULT1]], ptr [[I]], align 4
// CHECK-NEXT:    [[TMP2:%.*]] = load i32, ptr [[I]], align 4
